<?php
declare(strict_types=1);session_start();require dirname(__DIR__).'/config/config.php';require_sign_in();
$uid=(int)$_SESSION['user_id'];$role=(string)$_SESSION['role'];$allowed=['admin','director','sub_director','headteacher','bursar'];if(!in_array($role,$allowed,true)){http_response_code(403);exit('Your role cannot access school fee statements.');}
$school=filter_var($_GET['school_id']??null,FILTER_VALIDATE_INT);$pupilId=filter_var($_GET['pupil_id']??null,FILTER_VALIDATE_INT);if(!$school||!$pupilId){http_response_code(422);exit('Choose a school and pupil.');}$db=db();$q=$db->prepare('SELECT s.name school_name,p.id,p.admission_number,p.first_name,p.middle_name,p.last_name,p.class_level,p.stream,p.status FROM schools s JOIN school_memberships m ON m.school_id=s.id AND m.user_id=? JOIN pupils p ON p.school_id=s.id AND p.id=? WHERE s.id=?');$q->execute([$uid,$pupilId,$school]);$account=$q->fetch();if(!$account){http_response_code(404);exit('Pupil account not found in an accessible school.');}$q=$db->prepare('SELECT l.id,l.entry_type,l.academic_year,l.term,l.description,l.amount,l.payment_method,l.reference,l.reversal_of,l.reversal_reason,l.created_at,u.name recorder FROM school_fee_ledger l JOIN users u ON u.id=l.recorded_by WHERE l.school_id=? AND l.pupil_id=? ORDER BY l.created_at,l.id');$q->execute([$school,$pupilId]);$entries=$q->fetchAll();$balance=0.0;$charges=0.0;$payments=0.0;$running=[];foreach($entries as $entry){$amount=(float)$entry['amount'];$increase=in_array($entry['entry_type'],['charge','payment_reversal','discount_reversal'],true);$balance+=$increase?$amount:-$amount;if(in_array($entry['entry_type'],['charge','charge_reversal','discount','discount_reversal'],true))$charges+=(in_array($entry['entry_type'],['charge','discount_reversal'],true)?$amount:-$amount);else$payments+=($entry['entry_type']==='payment'?$amount:-$amount);$running[]=$balance;}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Fee statement · ShuleLite</title><link rel="stylesheet" href="assets/app.css"><style>@media print{.sidebar,.topbar,.screen-only,.page-footer{display:none!important}.main-area{margin:0!important;padding:0!important}.page-content{max-width:none!important;padding:0!important}.content-section,.metric-card{box-shadow:none!important;break-inside:avoid}.table-wrap{overflow:visible!important}table{min-width:0!important;font-size:10pt}body{background:#fff!important}}</style></head><body><div class="app-shell"><?php require __DIR__.'/sidebar.php';?><main class="main-area"><header class="topbar"><div class="crumb">School fees <span>/</span> Statement</div><div class="top-actions"><button class="button primary screen-only" type="button" onclick="window.print()">Print / Save PDF</button></div></header><div class="page-content"><section class="welcome-row"><div><div class="eyebrow">PUPIL FEE ACCOUNT</div><h1>Fee statement</h1><p class="muted"><?=e($account['school_name'])?> · <?=e(trim($account['first_name'].' '.($account['middle_name']??'').' '.$account['last_name']))?> · <?=e($account['admission_number'])?></p><p class="muted"><?=e($account['class_level'].($account['stream']?' · '.$account['stream']:'').' · '.ucfirst($account['status']))?></p></div><a class="button screen-only" href="accounting.php?school_id=<?=$school?>&amp;pupil_id=<?=$pupilId?>">Back to fee account</a></section><section class="metric-grid"><article class="metric-card"><div class="metric-label">NET CHARGES</div><div class="metric-value">KES <?=number_format($charges,2)?></div></article><article class="metric-card"><div class="metric-label">NET PAYMENTS</div><div class="metric-value">KES <?=number_format($payments,2)?></div></article><article class="metric-card"><div class="metric-label">BALANCE</div><div class="metric-value">KES <?=number_format($balance,2)?></div><div class="metric-note"><?=e($balance>0?'Outstanding':($balance<0?'Credit balance':'Settled'))?></div></article></section><section class="content-section"><div class="section-heading"><div><div class="eyebrow">ACCOUNT HISTORY</div><h2>Transactions</h2><p class="muted">All original entries and reversals are retained. Amounts in the statement are signed from the pupil account’s perspective.</p></div></div><?php if($entries):?><div class="table-wrap"><table><thead><tr><th>Date</th><th>Academic year / term</th><th>Entry</th><th>Description</th><th>Debit / credit (KES)</th><th>Payment details</th><th>Recorded by</th><th>Running balance (KES)</th></tr></thead><tbody><?php foreach($entries as $i=>$entry):$isDebit=in_array($entry['entry_type'],['charge','payment_reversal','discount_reversal'],true);?><tr><td><?=e(date('j M Y H:i',strtotime($entry['created_at'])))?></td><td><?=e($entry['academic_year'].' · '.$entry['term'])?></td><td><?=e(ucwords(str_replace('_',' ',$entry['entry_type'])))?><?php if($entry['reversal_of']):?> · reverses #<?=e((string)$entry['reversal_of'])?><?php endif;?></td><td><?=e($entry['description'].($entry['reversal_reason']?' · '.$entry['reversal_reason']:''))?></td><td><?=e(($isDebit?'+':'−').' '.number_format((float)$entry['amount'],2))?></td><td><?=e(trim(($entry['payment_method']??'').' '.($entry['reference']??''))?:'—')?></td><td><?=e($entry['recorder'])?></td><td><?=number_format($running[$i],2)?></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty-state"><h2>No transactions yet</h2><p>This pupil has no recorded fee charges or payments.</p></div><?php endif;?></section><p class="muted">This statement is generated from the school fee ledger. It is not a tax invoice or a request to pay.</p><footer class="page-footer">ShuleLite · Fee statement · <?=date('j M Y H:i')?></footer></div></main></div></div></body></html>
